func TestIndexRevisionsWithTotalCount(t *testing.T) {
	allKeys := [][]byte{[]byte("foo"), []byte("foo1"), []byte("foo2"), []byte("foo2"), []byte("foo1"), []byte("foo")}
	allRevs := []Revision{{Main: 1}, {Main: 2}, {Main: 3}, {Main: 4}, {Main: 5}, {Main: 6}}

	ti := newTreeIndex(zaptest.NewLogger(t))
	for i := range allKeys {
		ti.Put(allKeys[i], allRevs[i])
	}

	// Range [foo, fop) @ rev 6 matches 3 keys: foo, foo1, foo2.
	tests := []struct {
		name           string
		key, end       []byte
		atRev          int64
		limit          int
		withTotalCount bool
		wrevs          []Revision
		wtotal         int
	}{
		{
			name:           "withTotalCount=true with limit returns the full total",
			key:            []byte("foo"),
			end:            []byte("fop"),
			atRev:          6,
			limit:          1,
			withTotalCount: true,
			wrevs:          []Revision{{Main: 6}},
			wtotal:         3,
		},
		{
			name:           "withTotalCount=false with limit caps total at len(revs)",
			key:            []byte("foo"),
			end:            []byte("fop"),
			atRev:          6,
			limit:          1,
			withTotalCount: false,
			wrevs:          []Revision{{Main: 6}},
			wtotal:         1,
		},
		{
			name:           "withTotalCount=false with limit larger than matches returns full total",
			key:            []byte("foo"),
			end:            []byte("fop"),
			atRev:          6,
			limit:          10,
			withTotalCount: false,
			wrevs:          []Revision{{Main: 6}, {Main: 5}, {Main: 4}},
			wtotal:         3,
		},
		{
			name:           "withTotalCount=false without limit returns full total",
			key:            []byte("foo"),
			end:            []byte("fop"),
			atRev:          6,
			limit:          0,
			withTotalCount: false,
			wrevs:          []Revision{{Main: 6}, {Main: 5}, {Main: 4}},
			wtotal:         3,
		},
		{
			name:           "withTotalCount=true without limit returns full total",
			key:            []byte("foo"),
			end:            []byte("fop"),
			atRev:          6,
			limit:          0,
			withTotalCount: true,
			wrevs:          []Revision{{Main: 6}, {Main: 5}, {Main: 4}},
			wtotal:         3,
		},
		{
			name:           "withTotalCount=false with no matches",
			key:            []byte("bar"),
			end:            []byte("baz"),
			atRev:          6,
			limit:          5,
			withTotalCount: false,
			wrevs:          nil,
			wtotal:         0,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			revs, total := ti.Revisions(tt.key, tt.end, tt.atRev, tt.limit, tt.withTotalCount)
			if !reflect.DeepEqual(revs, tt.wrevs) {
				t.Errorf("revs = %+v, want %+v", revs, tt.wrevs)
			}
			if total != tt.wtotal {
				t.Errorf("total = %d, want %d", total, tt.wtotal)
			}
		})
	}
}

func TestIndexCompactAndKeep(t *testing.T) {
	maxRev := int64(20)

	// key: "foo"
	// modified: 10
	// generations:
	//	{{10, 0}}
	//	{{1, 0}, {5, 0}, {9, 0}(t)}
	//
	// key: "foo1"
	// modified: 10, 1
	// generations:
	//	{{10, 1}}
	//	{{2, 0}, {6, 0}, {7, 0}(t)}
	//
	// key: "foo2"
	// modified: 8
	// generations:
	//	{empty}
	//	{{3, 0}, {4, 0}, {8, 0}(t)}
	//
	buildTreeIndex := func() index {
		ti := newTreeIndex(zaptest.NewLogger(t))

		ti.Put([]byte("foo"), Revision{Main: 1})
		ti.Put([]byte("foo1"), Revision{Main: 2})
		ti.Put([]byte("foo2"), Revision{Main: 3})
		ti.Put([]byte("foo2"), Revision{Main: 4})
		ti.Put([]byte("foo"), Revision{Main: 5})
		ti.Put([]byte("foo1"), Revision{Main: 6})
		require.NoError(t, ti.Tombstone([]byte("foo1"), Revision{Main: 7}))
	s := NewStore(zaptest.NewLogger(t), b, &lease.FakeLessor{}, StoreConfig{})
	defer cleanup(s, b)

	kvs := put3TestKVs(s)

	wrev := int64(4)
	tests := []struct {
		limit   int64
		wcounts int64
		wkvs    []*mvccpb.KeyValue
	}{
		// no limit
		{-1, 3, kvs},
		// no limit
		{0, 3, kvs},
		{1, 3, kvs[:1]},
		{2, 3, kvs[:2]},
		{3, 3, kvs},
		{100, 3, kvs},
	}
	for i, tt := range tests {
		r, err := f(s, []byte("foo"), []byte("foo3"), RangeOptions{Limit: tt.limit, WithTotalCount: true})
		if err != nil {
			t.Fatalf("#%d: range error (%v)", i, err)
		}
		if !cmp.Equal(r.KVs, tt.wkvs, protocmp.Transform()) {
			t.Errorf("#%d: kvs = %+v, want %+v", i, r.KVs, tt.wkvs)
		}
		if r.Rev != wrev {
			t.Errorf("#%d: rev = %d, want %d", i, r.Rev, wrev)
		}
		if tt.limit <= 0 || int(tt.limit) > len(kvs) {
			if r.Count != len(kvs) {
				t.Errorf("#%d: count = %d, want %d", i, r.Count, len(kvs))
			}
		} else if r.Count != int(tt.wcounts) {
			t.Errorf("#%d: count = %d, want %d", i, r.Count, tt.limit)
		}
	}
}

